    (F : bvmap 5 word) fc (m : mem) (ACEIL SB c R k nfree mfa auser muser stat lo : Z),
  SB_ok ACEIL SB -> (1 <= c <= 31)%Z -> R = rinfo (RIS_of SB) c ->
  (0 <= auser <= muser)%Z -> (muser < auser + k * ClassSize c)%Z -> (1 <= k <= 64)%Z -> (muser mod 2^18 = 0)%Z ->
